// RotaryMul op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_rotary_mul.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor rotary_mul(
    const at::Tensor &input,
    const at::Tensor &r1,
    const at::Tensor &r2,
    int64_t rotary_mode)
{
    TORCH_CHECK(input.dim() == 2, "input must be 2D [total_rows, D] after flattening");
    TORCH_CHECK(r1.dim() == 2, "r1 must be 2D [total_rows, D]");
    TORCH_CHECK(r2.dim() == 2, "r2 must be 2D [total_rows, D]");
    TORCH_CHECK(
        input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
            input.scalar_type() == at::kBFloat16,
        "input must be float16, float32, or bfloat16");
    TORCH_CHECK(r1.scalar_type() == input.scalar_type(), "r1 dtype must match input");
    TORCH_CHECK(r2.scalar_type() == input.scalar_type(), "r2 dtype must match input");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(r1.is_contiguous(), "r1 must be contiguous");
    TORCH_CHECK(r2.is_contiguous(), "r2 must be contiguous");
    TORCH_CHECK(rotary_mode == 0 || rotary_mode == 1, "rotary_mode must be 0 (half) or 1 (interleave)");

    int32_t M = static_cast<int32_t>(input.sizes()[0]);
    int32_t D = static_cast<int32_t>(input.sizes()[1]);
    TORCH_CHECK(D % 2 == 0, "last dimension D must be even");

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor y = at::empty_like(input);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (input.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (input.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(rotary_mul, blockDim,
                    input, r1, r2, y,
                    M, D, blockM, usedCoreNum, tasksPerCore,
                    rotary_mode, dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
