// AscendC RotaryMul kernel — pure Vector operator
// Supports float32, float16, bfloat16
// Two rotation modes: half (split and rotate) and interleave (even/odd interleave)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void PrepareInputFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutputFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
    }
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputCastRoundMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputCastRoundMode<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// RotaryMul Kernel — single_row strategy
// =========================================================================

template <typename dataType>
class RotaryMulKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
        int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int64_t rotaryMode)
    {
        this->M = M;
        this->D = D;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rotaryMode = rotaryMode;
        this->halfD = D / 2;

        uint64_t rowSizeInElems = static_cast<uint64_t>(M) * D;

        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), rowSizeInElems);
        r1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r1), rowSizeInElems);
        r2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r2), rowSizeInElems);
        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), rowSizeInElems);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= CeilDivI32(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
    {
        if (b == 0) { return 0; }
        return (a + b - 1) / b;
    }

    __aicore__ inline void InitAivBuffers()
    {
        uint32_t rowBytes = static_cast<uint32_t>(D) * sizeof(dataType);
        uint32_t rowFloatBytes = static_cast<uint32_t>(D) * sizeof(float);
        uint32_t halfFloatBytes = static_cast<uint32_t>(halfD) * sizeof(float);

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r1InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r2InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, rowBytes);

        pipe.InitBuffer(computeBuf1_, rowFloatBytes);
        pipe.InitBuffer(computeBuf2_, rowFloatBytes);
        pipe.InitBuffer(computeBuf3_, halfFloatBytes);
        pipe.InitBuffer(computeBuf4_, halfFloatBytes);

        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, rowFloatBytes);
            pipe.InitBuffer(r1CastBuf_, rowFloatBytes);
            pipe.InitBuffer(r2CastBuf_, rowFloatBytes);
            pipe.InitBuffer(yCastBuf_, rowFloatBytes);
        }
    }

    // ---------- CopyIn ----------
    __aicore__ inline void CopyInX(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, inputGM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyInR1(int32_t rowIdx)
    {
        r1InLocal_ = r1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r1InLocal_, r1GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r1InQueue_.EnQue(r1InLocal_);
    }

    __aicore__ inline void CopyInR2(int32_t rowIdx)
    {
        r2InLocal_ = r2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r2InLocal_, r2GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r2InQueue_.EnQue(r2InLocal_);
    }

    __aicore__ inline void CopyIn(int32_t rowIdx)
    {
        CopyInX(rowIdx);
        CopyInR1(rowIdx);
        CopyInR2(rowIdx);
    }

    // ---------- CopyOut ----------
    __aicore__ inline void CopyOut(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(outputGM_[static_cast<uint64_t>(rowIdx) * D], yOutLocal_, static_cast<uint32_t>(D));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    // ---------- Compute: half mode ----------
    // rotated = concat(-x2, x1) where x1 = input[:halfD], x2 = input[halfD:]
    __aicore__ inline void ComputeHalfMode()
    {
        // Get float32 compute buffers
        AscendC::LocalTensor<float> comp1 = computeBuf1_.Get<float>();
        AscendC::LocalTensor<float> comp2 = computeBuf2_.Get<float>();
        AscendC::LocalTensor<float> comp3 = computeBuf3_.Get<float>();
        // comp1 = xLocal (full row), comp2 = r1Local/r2Local/tmp
        // We'll reuse buffers carefully.

        // For half mode:
        // x1 = input[0:halfD], x2 = input[halfD:D]
        // x2_neg = -x2
        // rotated = [x2_neg, x1]

        // Load x2 into comp3 (size halfD)
        AscendC::DataCopyExtParams copyHalf;
        copyHalf.blockCount = static_cast<uint32_t>(halfD);
        copyHalf.blockLen = static_cast<uint32_t>(sizeof(float));
        copyHalf.srcStride = static_cast<uint32_t>(sizeof(float));
        copyHalf.dstStride = static_cast<uint32_t>(sizeof(float));
        copyHalf.rsv = 0;
        AscendC::DataCopy(comp3, xLocalFp32_[halfD], copyHalf);
        AscendC::PipeBarrier<PIPE_V>();

        // Negate x2 → comp3 = -x2
        AscendC::Muls(comp3, comp3, -1.0f, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // rotated[0:halfD] = comp3 (-x2)
        AscendC::DataCopy(rotatedLocal_, comp3, copyHalf);
        // rotated[halfD:D] = x1 (xLocalFp32_[0:halfD])
        AscendC::DataCopy(rotatedLocal_[halfD], xLocalFp32_, copyHalf);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---------- Compute: interleave mode ----------
    // input = [x0, x1, x2, x3, ...]
    // rotated = [-x1, x0, -x3, x2, ...]
    __aicore__ inline void ComputeInterleaveMode()
    {
        AscendC::LocalTensor<float> comp3 = computeBuf3_.Get<float>();
        AscendC::LocalTensor<float> comp4 = computeBuf4_.Get<float>();

        // Extract even-positioned elements: [x0, x2, x4, ...]
        {
            AscendC::DataCopyExtParams evenParams;
            evenParams.blockCount = static_cast<uint32_t>(halfD);
            evenParams.blockLen = static_cast<uint32_t>(sizeof(float));
            evenParams.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
            evenParams.dstStride = static_cast<uint32_t>(sizeof(float));
            evenParams.rsv = 0;
            AscendC::DataCopy(comp3, xLocalFp32_, evenParams);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Extract odd-positioned elements: [x1, x3, x5, ...]
        {
            AscendC::DataCopyExtParams oddParams;
            oddParams.blockCount = static_cast<uint32_t>(halfD);
            oddParams.blockLen = static_cast<uint32_t>(sizeof(float));
            oddParams.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
            oddParams.dstStride = static_cast<uint32_t>(sizeof(float));
            oddParams.rsv = 0;
            AscendC::DataCopy(comp4, xLocalFp32_[1], oddParams);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Negate odds: comp4 = -comp4
        AscendC::Muls(comp4, comp4, -1.0f, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // Interleave back: comp4 (negated odds) → even positions, comp3 (evens) → odd positions
        {
            AscendC::DataCopyExtParams interEvens;
            interEvens.blockCount = static_cast<uint32_t>(halfD);
            interEvens.blockLen = static_cast<uint32_t>(sizeof(float));
            interEvens.srcStride = static_cast<uint32_t>(sizeof(float));
            interEvens.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
            interEvens.rsv = 0;
            AscendC::DataCopy(rotatedLocal_, comp4, interEvens);
        }

        {
            AscendC::DataCopyExtParams interOdds;
            interOdds.blockCount = static_cast<uint32_t>(halfD);
            interOdds.blockLen = static_cast<uint32_t>(sizeof(float));
            interOdds.srcStride = static_cast<uint32_t>(sizeof(float));
            interOdds.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
            interOdds.rsv = 0;
            AscendC::DataCopy(rotatedLocal_[1], comp3, interOdds);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---------- Compute ----------
    __aicore__ inline void Compute()
    {
        // Alloc output tensor
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

        // Alloc compute buffers
        xLocalFp32_ = computeBuf1_.Get<float>();
        r1LocalFp32_ = computeBuf2_.Get<float>();
        rotatedLocal_ = computeBuf1_.Get<float>();  // note: will overwrite xLocalFp32_ after use

        // --- Step 1: DeQue inputs ---
        xInLocal_ = xInQueue_.DeQue<dataType>();
        r1InLocal_ = r1InQueue_.DeQue<dataType>();
        r2InLocal_ = r2InQueue_.DeQue<dataType>();

        // --- Step 2: Cast inputs to FP32 ---
        PrepareInputFloat<dataType>(xLocalFp32_, xInLocal_, xCastBuf_, D);
        PrepareInputFloat<dataType>(r1LocalFp32_, r1InLocal_, r1CastBuf_, D);

        // Free input typed buffers early
        xInQueue_.FreeTensor(xInLocal_);
        r1InQueue_.FreeTensor(r1InLocal_);

        // --- Step 3: Compute rotated ---
        AscendC::PipeBarrier<PIPE_V>();

        if (rotaryMode == 0) {
            // half mode
            ComputeHalfMode();
        } else {
            // interleave mode
            ComputeInterleaveMode();
        }

        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 4: output = input * r1 + rotated * r2 ---
        // At this point:
        //   computeBuf2_ has r1LocalFp32_ (r1 in FP32)
        //   computeBuf1_ has rotatedLocal_ (rotated in FP32)
        // We need to compute: tmp1 = xLocalFp32_ * r1LocalFp32_
        //                    (overwrite xLocalFp32_)
        // Wait! xLocalFp32_ was using computeBuf1_ which now has rotatedLocal_
        // We need to reload xLocalFp32_ from computeBuf1_

        // Actually, we need to be careful about buffer aliasing. Let me restructure:
        // After ComputeHalfMode/ComputeInterleaveMode:
        //   computeBuf1_ → rotatedLocal_ (D elements in float32)

        // We need to compute:
        //   tmp1 = xLocalFp32_ * r1LocalFp32_
        //   tmp2 = rotatedLocal_ * r2LocalFp32_
        //   y = tmp1 + tmp2

        // But xLocalFp32_ was in computeBuf1_ which now holds rotated.
        // Solution: We'll use computeBuf3_ (halfD * sizeof(float)) or similar.

        // Since D can be up to 128, computeBuf3_ is only halfD * sizeof(float) which may be too small.
        // Let me reconsider the buffer layout.

        // Actually, computeBuf2_ has r1LocalFp32_ and we can reuse it.
        // Let me restructure:
        // - Use xLocalFp32_ from computeBuf1_ (before overwriting)
        // - After rotated is computed, reuse computeBuf2_ for intermediate results

        // Hmm, this is getting complicated. Let me restructure the buffer usage:

        // Buffer plan:
        // computeBuf1_: D * sizeof(float) → xLocalFp32_
        // computeBuf2_: D * sizeof(float) → r1LocalFp32_, then tmp1
        // computeBuf3_: halfD * sizeof(float) → temp for interleave/half
