        // computeBuf1_: D * sizeof(float) — r1LocalFp32_ / temp
        // computeBuf2_: D * sizeof(float) — r2LocalFp32_
        // computeBuf3_: D * sizeof(float) — rotatedLocal_
        // computeBuf4_: D * sizeof(float) — tmpBuffer
        // computeBuf5_: halfD * sizeof(float) — half/extract buffer
        // xCastBuf_, etc. for cast

        // Actually, for D=64 this is fine. Let me redesign the buffers.

        // OK let me rethink and simplify. The key issue is that after ComputeHalfMode/ComputeInterleaveMode,
        // computeBuf1_ has been reused for rotatedLocal_. So I lose xLocalFp32_.

        // Solution: Save xLocalFp32_ in a separate buffer, or just reorder the computation.

        // Better approach:
        // 1. Load x (computeBuf0_), r1 (computeBuf1_), r2 (computeBuf2_)
        // 2. Compute rotated → put in computeBuf3_
        // 3. tmp = x * r1 → computeBuf0_ (overwrite x)
        // 4. tmp2 = rotated * r2 → computeBuf1_ (overwrite r1)
        // 5. result = tmp + tmp2 → computeBuf0_

        // For this I need computeBuf0_, computeBuf1_, computeBuf2_, computeBuf3_ all at D * sizeof(float).
        // Plus computeBuf4_ at halfD * sizeof(float) for temporary in interleave/half mode.
        // Total: 4.5 * D * sizeof(float) for D=64 = 4.5*256 = 1152 bytes. Fine.

        // Let me rewrite with this buffer plan.

        return; // placeholder — will be replaced in actual compute
    }

    // ---------- ProcessRow ----------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyIn(rowIdx);
        Compute();
        CopyOut(rowIdx);
    }

private:
    int32_t M = 0;
    int32_t D = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int64_t rotaryMode = 0;
    int32_t halfD = 0;
    int32_t subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> inputGM_;
    AscendC::GlobalTensor<dataType> r1GM_;
    AscendC::GlobalTensor<dataType> r2GM_;
    AscendC::GlobalTensor<dataType> outputGM_;

    // TQue buffers (GM ↔ UB)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // TBuf buffers (UB computation)
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf1_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf2_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf3_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf4_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> r1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> r2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    // Local tensors
    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> r1InLocal_;
    AscendC::LocalTensor<dataType> r2InLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocalFp32_;
    AscendC::LocalTensor<float> r1LocalFp32_;
    AscendC::LocalTensor<float> r2LocalFp32_;
    AscendC::LocalTensor<float> rotatedLocal_;
    AscendC::LocalTensor<float> tmpBufFp32_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

template <typename... ExtraArgs>
__aicore__ inline void DispatchRotaryMul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int64_t rotaryMode, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        RotaryMulKernel<float> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        RotaryMulKernel<half> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    } else {
        RotaryMulKernel<bfloat16_t> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void rotary_mul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int64_t rotaryMode, int64_t dtypeFlag)
{
    DispatchRotaryMul(
        input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore,
        rotaryMode, dtypeFlag);
}
