50	template <typename T>
51	__aicore__ inline void PrepareInputFloat(
52	    AscendC::LocalTensor<float> &dst,
53	    AscendC::LocalTensor<T> &src,
54	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
55	    int32_t count)
56	{
57	    if constexpr (std::is_same_v<T, float>) {
58	        dst = src.template ReinterpretCast<float>();
59	    } else {
60	        dst = castBuf.Get<float>();
61	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
62	        AscendC::PipeBarrier<PIPE_V>();
63	    }
64	}
