67	__aicore__ inline void PrepareOutputFloat(
68	    AscendC::LocalTensor<float> &dst,
69	    AscendC::LocalTensor<T> &out,
70	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
71	{
72	    if constexpr (std::is_same_v<T, float>) {
73	        dst = out.template ReinterpretCast<float>();
74	    } else {
75	        dst = castBuf.Get<float>();
76	    }
77	}
