100	// =========================================================================
101	// RotaryMul Kernel — single_row strategy
102	// =========================================================================
103	
104	template <typename dataType>
105	class RotaryMulKernel {
106	public:
107	    __aicore__ inline void Init(
108	        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
109	        int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
110	        int32_t tasksPerCore, int64_t rotaryMode)
111	    {
112	        this->M = M;
113	        this->D = D;
114	        this->blockM = blockM;
115	        this->usedCoreNum = usedCoreNum;
116	        this->tasksPerCore = tasksPerCore;
117	        this->rotaryMode = rotaryMode;
118	        this->halfD = D / 2;
119	
120	        uint64_t rowSizeInElems = static_cast<uint64_t>(M) * D;
121	
122	        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), rowSizeInElems);
123	        r1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r1), rowSizeInElems);
124	        r2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r2), rowSizeInElems);
125	        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), rowSizeInElems);
126	
127	        if ASCEND_IS_AIV { InitAivBuffers(); }
128	    }
129	
130	    __aicore__ inline void Process()
131	    {
132	        if ASCEND_IS_AIV {
133	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
134	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
135	            const int subBlockIdx = AscendC::GetSubBlockIdx();
136	
137	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
138	                const int bx = coreIdx * tasksPerCore + localIdx;
139	                if (bx >= CeilDivI32(M, blockM)) {
140	                    continue;
141	                }
142	
143	                for (int row = 0; row < subBlockRows_; ++row) {
144	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
145	                    if (rowIdx < M) {
146	                        ProcessRow(rowIdx);
147	                    }
148	                }
149	            }
150	        }
151	    }
152	
153	private:
154	    __aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
155	    {
156	        if (b == 0) { return 0; }
157	        return (a + b - 1) / b;
158	    }
159	
160	    __aicore__ inline void InitAivBuffers()
161	    {
162	        uint32_t rowBytes = static_cast<uint32_t>(D) * sizeof(dataType);
163	        uint32_t rowFloatBytes = static_cast<uint32_t>(D) * sizeof(float);
164	        uint32_t halfFloatBytes = static_cast<uint32_t>(halfD) * sizeof(float);
165	
166	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
167	        pipe.InitBuffer(r1InQueue_, BUFFER_NUM, rowBytes);
168	        pipe.InitBuffer(r2InQueue_, BUFFER_NUM, rowBytes);
169	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, rowBytes);
170	
171	        pipe.InitBuffer(computeBuf1_, rowFloatBytes);
172	        pipe.InitBuffer(computeBuf2_, rowFloatBytes);
173	        pipe.InitBuffer(computeBuf3_, halfFloatBytes);
174	        pipe.InitBuffer(computeBuf4_, halfFloatBytes);
175	
176	        if constexpr (!std::is_same_v<dataType, float>) {
177	            pipe.InitBuffer(xCastBuf_, rowFloatBytes);
178	            pipe.InitBuffer(r1CastBuf_, rowFloatBytes);
179	            pipe.InitBuffer(r2CastBuf_, rowFloatBytes);
180	            pipe.InitBuffer(yCastBuf_, rowFloatBytes);
181	        }
182	    }
183	
184	    // ---------- CopyIn ----------
185	    __aicore__ inline void CopyInX(int32_t rowIdx)
186	    {
187	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
188	        LoadGmToUb(xInLocal_, inputGM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
189	        xInQueue_.EnQue(xInLocal_);
190	    }
191	
192	    __aicore__ inline void CopyInR1(int32_t rowIdx)
193	    {
194	        r1InLocal_ = r1InQueue_.AllocTensor<dataType>();
195	        LoadGmToUb(r1InLocal_, r1GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
196	        r1InQueue_.EnQue(r1InLocal_);
197	    }
198	
199	    __aicore__ inline void CopyInR2(int32_t rowIdx)
200	    {
201	        r2InLocal_ = r2InQueue_.AllocTensor<dataType>();
202	        LoadGmToUb(r2InLocal_, r2GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
203	        r2InQueue_.EnQue(r2InLocal_);
204	    }
205	
206	    __aicore__ inline void CopyIn(int32_t rowIdx)
207	    {
208	        CopyInX(rowIdx);
209	        CopyInR1(rowIdx);
210	        CopyInR2(rowIdx);
211	    }
212	
213	    // ---------- CopyOut ----------
214	    __aicore__ inline void CopyOut(int32_t rowIdx)
215	    {
216	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
217	        StoreUbToGm(outputGM_[static_cast<uint64_t>(rowIdx) * D], yOutLocal_, static_cast<uint32_t>(D));
218	        yOutQueue_.FreeTensor(yOutLocal_);
219	    }
220	
221	    // ---------- Compute: half mode ----------
222	    // rotated = concat(-x2, x1) where x1 = input[:halfD], x2 = input[halfD:]
223	    __aicore__ inline void ComputeHalfMode()
224	    {
225	        // Get float32 compute buffers
226	        AscendC::LocalTensor<float> comp1 = computeBuf1_.Get<float>();
227	        AscendC::LocalTensor<float> comp2 = computeBuf2_.Get<float>();
228	        AscendC::LocalTensor<float> comp3 = computeBuf3_.Get<float>();
229	        // comp1 = xLocal (full row), comp2 = r1Local/r2Local/tmp
230	        // We'll reuse buffers carefully.
231	
232	        // For half mode:
233	        // x1 = input[0:halfD], x2 = input[halfD:D]
234	        // x2_neg = -x2
235	        // rotated = [x2_neg, x1]
236	
237	        // Load x2 into comp3 (size halfD)
238	        AscendC::DataCopyExtParams copyHalf;
239	        copyHalf.blockCount = static_cast<uint32_t>(halfD);
240	        copyHalf.blockLen = static_cast<uint32_t>(sizeof(float));
241	        copyHalf.srcStride = static_cast<uint32_t>(sizeof(float));
242	        copyHalf.dstStride = static_cast<uint32_t>(sizeof(float));
243	        copyHalf.rsv = 0;
244	        AscendC::DataCopy(comp3, xLocalFp32_[halfD], copyHalf);
245	        AscendC::PipeBarrier<PIPE_V>();
246	
247	        // Negate x2 → comp3 = -x2
248	        AscendC::Muls(comp3, comp3, -1.0f, halfD);
249	        AscendC::PipeBarrier<PIPE_V>();
250	
251	        // rotated[0:halfD] = comp3 (-x2)
252	        AscendC::DataCopy(rotatedLocal_, comp3, copyHalf);
253	        // rotated[halfD:D] = x1 (xLocalFp32_[0:halfD])
254	        AscendC::DataCopy(rotatedLocal_[halfD], xLocalFp32_, copyHalf);
255	        AscendC::PipeBarrier<PIPE_V>();
256	    }
257	
258	    // ---------- Compute: interleave mode ----------
259	    // input = [x0, x1, x2, x3, ...]
260	    // rotated = [-x1, x0, -x3, x2, ...]
261	    __aicore__ inline void ComputeInterleaveMode()
262	    {
263	        AscendC::LocalTensor<float> comp3 = computeBuf3_.Get<float>();
264	        AscendC::LocalTensor<float> comp4 = computeBuf4_.Get<float>();
265	
266	        // Extract even-positioned elements: [x0, x2, x4, ...]
267	        {
268	            AscendC::DataCopyExtParams evenParams;
269	            evenParams.blockCount = static_cast<uint32_t>(halfD);
270	            evenParams.blockLen = static_cast<uint32_t>(sizeof(float));
271	            evenParams.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
272	            evenParams.dstStride = static_cast<uint32_t>(sizeof(float));
273	            evenParams.rsv = 0;
274	            AscendC::DataCopy(comp3, xLocalFp32_, evenParams);
275	        }
276	        AscendC::PipeBarrier<PIPE_V>();
277	
278	        // Extract odd-positioned elements: [x1, x3, x5, ...]
279	        {
280	            AscendC::DataCopyExtParams oddParams;
281	            oddParams.blockCount = static_cast<uint32_t>(halfD);
282	            oddParams.blockLen = static_cast<uint32_t>(sizeof(float));
283	            oddParams.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
284	            oddParams.dstStride = static_cast<uint32_t>(sizeof(float));
285	            oddParams.rsv = 0;
286	            AscendC::DataCopy(comp4, xLocalFp32_[1], oddParams);
287	        }
288	        AscendC::PipeBarrier<PIPE_V>();
289	
290	        // Negate odds: comp4 = -comp4
291	        AscendC::Muls(comp4, comp4, -1.0f, halfD);
292	        AscendC::PipeBarrier<PIPE_V>();
293	
294	        // Interleave back: comp4 (negated odds) → even positions, comp3 (evens) → odd positions
295	        {
296	            AscendC::DataCopyExtParams interEvens;
297	            interEvens.blockCount = static_cast<uint32_t>(halfD);
298	            interEvens.blockLen = static_cast<uint32_t>(sizeof(float));
299	            interEvens.srcStride = static_cast<uint32_t>(sizeof(float));
300	            interEvens.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
301	            interEvens.rsv = 0;
302	            AscendC::DataCopy(rotatedLocal_, comp4, interEvens);
303	        }
304	
305	        {
306	            AscendC::DataCopyExtParams interOdds;
307	            interOdds.blockCount = static_cast<uint32_t>(halfD);
308	            interOdds.blockLen = static_cast<uint32_t>(sizeof(float));
309	            interOdds.srcStride = static_cast<uint32_t>(sizeof(float));
310	            interOdds.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
311	            interOdds.rsv = 0;
312	            AscendC::DataCopy(rotatedLocal_[1], comp3, interOdds);
313	        }
314	        AscendC::PipeBarrier<PIPE_V>();
315	    }
316	
317	    // ---------- Compute ----------
318	    __aicore__ inline void Compute()
319	    {
320	        // Alloc output tensor
321	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
322	
323	        // Alloc compute buffers
324	        xLocalFp32_ = computeBuf1_.Get<float>();
325	        r1LocalFp32_ = computeBuf2_.Get<float>();
326	        rotatedLocal_ = computeBuf1_.Get<float>();  // note: will overwrite xLocalFp32_ after use
327	
328	        // --- Step 1: DeQue inputs ---
329	        xInLocal_ = xInQueue_.DeQue<dataType>();
330	        r1InLocal_ = r1InQueue_.DeQue<dataType>();
331	        r2InLocal_ = r2InQueue_.DeQue<dataType>();
332	
333	        // --- Step 2: Cast inputs to FP32 ---
334	        PrepareInputFloat<dataType>(xLocalFp32_, xInLocal_, xCastBuf_, D);
335	        PrepareInputFloat<dataType>(r1LocalFp32_, r1InLocal_, r1CastBuf_, D);
336	
337	        // Free input typed buffers early
338	        xInQueue_.FreeTensor(xInLocal_);
339	        r1InQueue_.FreeTensor(r1InLocal_);
340	
341	        // --- Step 3: Compute rotated ---
342	        AscendC::PipeBarrier<PIPE_V>();
343	
344	        if (rotaryMode == 0) {
345	            // half mode
346	            ComputeHalfMode();
347	        } else {
348	            // interleave mode
349	            ComputeInterleaveMode();
350	        }
351	
352	        AscendC::PipeBarrier<PIPE_V>();
353	
354	        // --- Step 4: output = input * r1 + rotated * r2 ---
355	        // At this point:
356	        //   computeBuf2_ has r1LocalFp32_ (r1 in FP32)
357	        //   computeBuf1_ has rotatedLocal_ (rotated in FP32)
358	        // We need to compute: tmp1 = xLocalFp32_ * r1LocalFp32_
359	        //                    (overwrite xLocalFp32_)
360	        // Wait! xLocalFp32_ was using computeBuf1_ which now has rotatedLocal_
361	        // We need to reload xLocalFp32_ from computeBuf1_
362	
363	        // Actually, we need to be careful about buffer aliasing. Let me restructure:
364	        // After ComputeHalfMode/ComputeInterleaveMode:
365	        //   computeBuf1_ → rotatedLocal_ (D elements in float32)
366	
367	        // We need to compute:
368	        //   tmp1 = xLocalFp32_ * r1LocalFp32_
369	        //   tmp2 = rotatedLocal_ * r2LocalFp32_
370	        //   y = tmp1 + tmp2
371	
372	        // But xLocalFp32_ was in computeBuf1_ which now holds rotated.
373	        // Solution: We'll use computeBuf3_ (halfD * sizeof(float)) or similar.
374	
375	        // Since D can be up to 128, computeBuf3_ is only halfD * sizeof(float) which may be too small.
376	        // Let me reconsider the buffer layout.
377	
378	        // Actually, computeBuf2_ has r1LocalFp32_ and we can reuse it.
379	        // Let me restructure:
380	        // - Use xLocalFp32_ from computeBuf1_ (before overwriting)
381	        // - After rotated is computed, reuse computeBuf2_ for intermediate results
382	
383	        // Hmm, this is getting complicated. Let me restructure the buffer usage:
384	
385	        // Buffer plan:
386	        // computeBuf1_: D * sizeof(float) → xLocalFp32_
387	        // computeBuf2_: D * sizeof(float) → r1LocalFp32_, then tmp1
388	        // computeBuf3_: halfD * sizeof(float) → temp for interleave/half
389	        // computeBuf4_: halfD * sizeof(float) → temp for interleave
390	
391	        // But for the multiplication step, I need:
392	        // xLocalFp32_ (from computeBuf1_) — loaded input
393	        // r1LocalFp32_ (from computeBuf2_) — loaded r1
394	        // r2LocalFp32_ — need another buffer
395	        // rotatedLocal_ — need another buffer
396	        // temp — for intermediate
397	
398	        // That's 4-5 buffers with D elements each! But we only have:
399	        // computeBuf1_: D elements
400	        // computeBuf2_: D elements
401	        // computeBuf3_: D/2 elements
402	        // computeBuf4_: D/2 elements
403	
404	        // For half mode: need x (D), r1 (D), r2 (D), rotated (D), temp (D)
405	        // But D=64, sizeof(float)=4, so each D buffer = 256 bytes. Total = 1280 bytes + cast bufs.
406	        // UB size is typically 256KB, so plenty of room.
407	
408	        // Let me allocate more buffers for FP32 compute. I'll add more compute buffers.
409	
410	        // Updated plan: BUFFER_NUM = 2 for double buffering of input queues.
411	        // Compute buffers:
412	        // computeBuf0_: D * sizeof(float) — xLocalFp32_
413	        // computeBuf1_: D * sizeof(float) — r1LocalFp32_ / temp
414	        // computeBuf2_: D * sizeof(float) — r2LocalFp32_
415	        // computeBuf3_: D * sizeof(float) — rotatedLocal_
416	        // computeBuf4_: D * sizeof(float) — tmpBuffer
417	        // computeBuf5_: halfD * sizeof(float) — half/extract buffer
418	        // xCastBuf_, etc. for cast
419	
420	        // Actually, for D=64 this is fine. Let me redesign the buffers.
421	
422	        // OK let me rethink and simplify. The key issue is that after ComputeHalfMode/ComputeInterleaveMode,
423	        // computeBuf1_ has been reused for rotatedLocal_. So I lose xLocalFp32_.
424	
425	        // Solution: Save xLocalFp32_ in a separate buffer, or just reorder the computation.
426	
427	        // Better approach:
428	        // 1. Load x (computeBuf0_), r1 (computeBuf1_), r2 (computeBuf2_)
429	        // 2. Compute rotated → put in computeBuf3_
430	        // 3. tmp = x * r1 → computeBuf0_ (overwrite x)
431	        // 4. tmp2 = rotated * r2 → computeBuf1_ (overwrite r1)
432	        // 5. result = tmp + tmp2 → computeBuf0_
433	
434	        // For this I need computeBuf0_, computeBuf1_, computeBuf2_, computeBuf3_ all at D * sizeof(float).
435	        // Plus computeBuf4_ at halfD * sizeof(float) for temporary in interleave/half mode.
436	        // Total: 4.5 * D * sizeof(float) for D=64 = 4.5*256 = 1152 bytes. Fine.
437	
438	        // Let me rewrite with this buffer plan.
439	
440	        return; // placeholder — will be replaced in actual compute
441	    }
442	
443	    // ---------- ProcessRow ----------
444	    __aicore__ inline void ProcessRow(int32_t rowIdx)
445	    {
446	        CopyIn(rowIdx);
447	        Compute();
448	        CopyOut(rowIdx);
449	    }
450	
451	private:
452	    int32_t M = 0;
453	    int32_t D = 0;
454	    int32_t blockM = 0;
455	    int32_t usedCoreNum = 0;
