// AscendC RotaryMul kernel — pure Vector operator
// Supports float32, float16, bfloat16
// Two rotation modes: half (split and rotate) and interleave (even/odd interleave)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void PrepareInputFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputCastRoundMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputCastRoundMode<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// RotaryMul Kernel — single_row strategy, pure Vector
// =========================================================================

template <typename dataType>
class RotaryMulKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
        int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int64_t rotaryMode)
    {
        this->M = M;
        this->D = D;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rotaryMode = rotaryMode;
        this->halfD = D / 2;

        uint64_t rowSizeInElems = static_cast<uint64_t>(M) * D;

        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), rowSizeInElems);
        r1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r1), rowSizeInElems);
        r2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r2), rowSizeInElems);
        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), rowSizeInElems);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= CeilDivI32(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers()
    {
        uint32_t rowBytes = static_cast<uint32_t>(D) * sizeof(dataType);
        uint32_t rowFloatBytes = static_cast<uint32_t>(D) * sizeof(float);
        uint32_t halfFloatBytes = static_cast<uint32_t>(halfD) * sizeof(float);

        // TQue buffers for GM↔UB data movement (double-buffered)
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r1InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r2InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, rowBytes);

        // TBuf FP32 compute buffers
        pipe.InitBuffer(bufX_, rowFloatBytes);        // x input in FP32
        pipe.InitBuffer(bufR1_, rowFloatBytes);       // r1 in FP32
        pipe.InitBuffer(bufR2_, rowFloatBytes);       // r2 in FP32
        pipe.InitBuffer(bufRot_, rowFloatBytes);      // rotated in FP32
        pipe.InitBuffer(bufTmp_, rowFloatBytes);      // tmp for intermediate results
        pipe.InitBuffer(bufExt1_, halfFloatBytes);    // extract buffer 1
        pipe.InitBuffer(bufExt2_, halfFloatBytes);    // extract buffer 2

        // Cast buffers for FP16/BF16
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, rowFloatBytes);
            pipe.InitBuffer(r1CastBuf_, rowFloatBytes);
            pipe.InitBuffer(r2CastBuf_, rowFloatBytes);
            pipe.InitBuffer(yCastBuf_, rowFloatBytes);
        }
    }

    // ---------- CopyIn ----------
    __aicore__ inline void CopyInX(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, inputGM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyInR1(int32_t rowIdx)
    {
        r1InLocal_ = r1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r1InLocal_, r1GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r1InQueue_.EnQue(r1InLocal_);
    }

    __aicore__ inline void CopyInR2(int32_t rowIdx)
    {
        r2InLocal_ = r2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r2InLocal_, r2GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r2InQueue_.EnQue(r2InLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(outputGM_[static_cast<uint64_t>(rowIdx) * D], yOutLocal_, static_cast<uint32_t>(D));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    // ---------- ComputeRotated: half mode ----------
    // rotated = concat(-x2, x1) where x1 = x[:halfD], x2 = x[halfD:]
    __aicore__ inline void ComputeRotatedHalf(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &rotLocal,
        AscendC::LocalTensor<float> &ext1)
    {
        AscendC::DataCopyExtParams cp;
        cp.blockCount = static_cast<uint32_t>(halfD);
        cp.blockLen = static_cast<uint32_t>(sizeof(float));
        cp.srcStride = static_cast<uint32_t>(sizeof(float));
        cp.dstStride = static_cast<uint32_t>(sizeof(float));
        cp.rsv = 0;

        // ext1 = x[halfD:D] (x2)
        AscendC::DataCopy(ext1, xLocal[halfD], cp);
        AscendC::PipeBarrier<PIPE_V>();

        // ext1 = -x2
        AscendC::Muls(ext1, ext1, -1.0f, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // rot[0:halfD] = -x2
        AscendC::DataCopy(rotLocal, ext1, cp);
        // rot[halfD:D] = x1
        AscendC::DataCopy(rotLocal[halfD], xLocal, cp);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---------- ComputeRotated: interleave mode ----------
    // input = [x0, x1, x2, x3, ...]
    // rotated = [-x1, x0, -x3, x2, ...]
    __aicore__ inline void ComputeRotatedInterleave(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &rotLocal,
        AscendC::LocalTensor<float> &ext1,
        AscendC::LocalTensor<float> &ext2)
    {
        // Extract even-positioned elements: [x0, x2, x4, ...]
        {
            AscendC::DataCopyExtParams cp;
            cp.blockCount = static_cast<uint32_t>(halfD);
            cp.blockLen = static_cast<uint32_t>(sizeof(float));
            cp.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
            cp.dstStride = static_cast<uint32_t>(sizeof(float));
            cp.rsv = 0;
            AscendC::DataCopy(ext1, xLocal, cp);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Extract odd-positioned elements: [x1, x3, x5, ...]
        {
            AscendC::DataCopyExtParams cp;
            cp.blockCount = static_cast<uint32_t>(halfD);
            cp.blockLen = static_cast<uint32_t>(sizeof(float));
            cp.srcStride = 2U * static_cast<uint32_t>(sizeof(float));
            cp.dstStride = static_cast<uint32_t>(sizeof(float));
            cp.rsv = 0;
            AscendC::DataCopy(ext2, xLocal[1], cp);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Negate odds: ext2 = -ext2
        AscendC::Muls(ext2, ext2, -1.0f, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // Interleave back:
        // ext2 (negated odds) → even positions of rot
        {
            AscendC::DataCopyExtParams cp;
            cp.blockCount = static_cast<uint32_t>(halfD);
            cp.blockLen = static_cast<uint32_t>(sizeof(float));
            cp.srcStride = static_cast<uint32_t>(sizeof(float));
            cp.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
            cp.rsv = 0;
            AscendC::DataCopy(rotLocal, ext2, cp);
        }
        // ext1 (evens) → odd positions of rot
        {
            AscendC::DataCopyExtParams cp;
            cp.blockCount = static_cast<uint32_t>(halfD);
            cp.blockLen = static_cast<uint32_t>(sizeof(float));
            cp.srcStride = static_cast<uint32_t>(sizeof(float));
            cp.dstStride = 2U * static_cast<uint32_t>(sizeof(float));
            cp.rsv = 0;
            AscendC::DataCopy(rotLocal[1], ext1, cp);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---------- Compute ----------
    __aicore__ inline void Compute()
    {
        // Get FP32 compute buffers
        AscendC::LocalTensor<float> xLocal = bufX_.Get<float>();
        AscendC::LocalTensor<float> r1Local = bufR1_.Get<float>();
        AscendC::LocalTensor<float> r2Local = bufR2_.Get<float>();
        AscendC::LocalTensor<float> rotLocal = bufRot_.Get<float>();
        AscendC::LocalTensor<float> tmpLocal = bufTmp_.Get<float>();
        AscendC::LocalTensor<float> ext1 = bufExt1_.Get<float>();
        AscendC::LocalTensor<float> ext2 = bufExt2_.Get<float>();

        // Alloc output typed tensor from TQue
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

        // --- Step 1: DeQue inputs ---
        xInLocal_ = xInQueue_.DeQue<dataType>();
        r1InLocal_ = r1InQueue_.DeQue<dataType>();
        r2InLocal_ = r2InQueue_.DeQue<dataType>();

        // --- Step 2: Cast inputs to FP32 ---
        PrepareInputFloat<dataType>(xLocal, xInLocal_, xCastBuf_, D);
        PrepareInputFloat<dataType>(r1Local, r1InLocal_, r1CastBuf_, D);

        // Free typed input tensors early (r2 still needed)
        xInQueue_.FreeTensor(xInLocal_);
        r1InQueue_.FreeTensor(r1InLocal_);

        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 3: Compute rotated from x ---
        if (rotaryMode == 0) {
            ComputeRotatedHalf(xLocal, rotLocal, ext1);
        } else {
            ComputeRotatedInterleave(xLocal, rotLocal, ext1, ext2);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 4: Cast r2 to FP32 ---
        PrepareInputFloat<dataType>(r2Local, r2InLocal_, r2CastBuf_, D);
        r2InQueue_.FreeTensor(r2InLocal_);
        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 5: output = input * r1 + rotated * r2 ---
        // tmpLocal = xLocal * r1Local
        AscendC::Mul(tmpLocal, xLocal, r1Local, D);
        AscendC::PipeBarrier<PIPE_V>();

        // xLocal = rotLocal * r2Local (reuse xLocal buffer)
        AscendC::Mul(xLocal, rotLocal, r2Local, D);
        AscendC::PipeBarrier<PIPE_V>();

        // tmpLocal = tmpLocal + xLocal = final output in FP32
        AscendC::Add(tmpLocal, tmpLocal, xLocal, D);
        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 6: Cast output to typed and EnQue ---
        if constexpr (std::is_same_v<dataType, float>) {
            // tmpLocal already contains the FP32 result;
            // we have ReinterpretCast the output typed tensor to float
            // Actually, for float dtype, we can just DataCopy from tmpLocal to output
        }
        // For non-float: Cast from FP32 to typed, then output
        FinalizeOutput<dataType>(yOutLocal_, tmpLocal, D);

        // EnQue the output for CopyOut
        yOutQueue_.EnQue(yOutLocal_);
    }

    // ---------- ProcessRow ----------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyInX(rowIdx);
        CopyInR1(rowIdx);
        CopyInR2(rowIdx);
        Compute();
        CopyOutY(rowIdx);
    }

private:
    int32_t M = 0;
    int32_t D = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int64_t rotaryMode = 0;
    int32_t halfD = 0;
    int32_t subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> inputGM_;
    AscendC::GlobalTensor<dataType> r1GM_;
    AscendC::GlobalTensor<dataType> r2GM_;
    AscendC::GlobalTensor<dataType> outputGM_;

    // TQue buffers (GM ↔ UB, double-buffered)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // TBuf compute buffers (FP32, VECCALC)
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufX_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufR1_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufR2_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufRot_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufTmp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufExt1_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufExt2_;

    // Cast buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> r1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> r2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    // LocalTensor members
    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> r1InLocal_;
    AscendC::LocalTensor<dataType> r2InLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

__aicore__ inline void DispatchRotaryMul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int64_t rotaryMode, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        RotaryMulKernel<float> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        RotaryMulKernel<half> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    } else {
        RotaryMulKernel<bfloat16_t> kernel;
        kernel.Init(input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore, rotaryMode);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void rotary_mul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int64_t rotaryMode, int64_t dtypeFlag)
{
    DispatchRotaryMul(
        input, r1, r2, output, M, D, blockM, usedCoreNum, tasksPerCore,
        rotaryMode, dtypeFlag);
}
