// AscendC RotaryMul kernel — pure Vector operator
// Supports float32, float16, bfloat16
// Two rotation modes: half and interleave

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void PrepareInputFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputCastRoundMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// ---------------------------------------------------------------------------
// Strider helper: copies data with stride between UB buffers using DataCopy
// ---------------------------------------------------------------------------
// Since CANN 8.5 DataCopy for Local→Local with DataCopyExtParams doesn't
// compile, we use DataCopyParams instead which supports stride via srcGap/dstGap.

// =========================================================================
// RotaryMul Kernel — single_row strategy, pure Vector
// =========================================================================
// Buffer plan (all UB, VECCALC):
//   buf0 = input fp32 (D)
//   buf1 = r1 fp32 (D)
//   buf2 = r2 fp32 (D)
//   buf3 = output/work (D)
//   buf4 = extracted evens/half (halfD)
//   buf5 = extracted odds/half (halfD)
//   buf6 = r1 evens/half (halfD)
//   buf7 = r1 odds/half (halfD)
//   buf8 = r2 evens/half (halfD)
//   buf9 = r2 odds/half (halfD)
// Total: ~5 * D + 5 * halfD = 7.5 * D elements = 7.5 * 128 * 4 = 3840 bytes max (fine for UB)
//
// Simplified formula for half mode:
//   out[:halfD] = x[:halfD] * r1[:halfD] - x[halfD:D] * r2[:halfD]
//   out[halfD:D] = x[halfD:D] * r1[halfD:D] + x[:halfD] * r2[halfD:D]
//
// Simplified formula for interleave mode:
//   out_evens = x_evens * r1_evens - x_odds * r2_evens
//   out_odds  = x_odds  * r1_odds  + x_evens * r2_odds

template <typename dataType>
class RotaryMulKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
        int32_t M, int32_t D, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int64_t rotaryMode)
    {
        this->M = M;
        this->D = D;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rotaryMode = rotaryMode;
        this->halfD = D / 2;

        uint64_t rowSizeInElems = static_cast<uint64_t>(M) * D;

        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), rowSizeInElems);
        r1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r1), rowSizeInElems);
        r2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(r2), rowSizeInElems);
        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), rowSizeInElems);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= CeilDivI32(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers()
    {
        uint32_t rowBytes = static_cast<uint32_t>(D) * sizeof(dataType);
        uint32_t rowFloat = static_cast<uint32_t>(D) * sizeof(float);
        uint32_t halfFloat = static_cast<uint32_t>(halfD) * sizeof(float);

        // TQue buffers for GM↔UB data movement
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r1InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(r2InQueue_, BUFFER_NUM, rowBytes);
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, rowBytes);

        // TBuf FP32 compute buffers
        pipe.InitBuffer(buf0_, rowFloat);   // x fp32
        pipe.InitBuffer(buf1_, rowFloat);   // r1 fp32
        pipe.InitBuffer(buf2_, rowFloat);   // r2 fp32
        pipe.InitBuffer(buf3_, rowFloat);   // output/work fp32
        pipe.InitBuffer(buf4_, halfFloat);  // extracted left half / evens
        pipe.InitBuffer(buf5_, halfFloat);  // extracted right half / odds
        pipe.InitBuffer(buf6_, halfFloat);  // r1 left / evens
        pipe.InitBuffer(buf7_, halfFloat);  // r1 right / odds
        pipe.InitBuffer(buf8_, halfFloat);  // r2 left / evens
        pipe.InitBuffer(buf9_, halfFloat);  // r2 right / odds

        // Cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, rowFloat);
            pipe.InitBuffer(r1CastBuf_, rowFloat);
            pipe.InitBuffer(r2CastBuf_, rowFloat);
            pipe.InitBuffer(yCastBuf_, rowFloat);
        }
    }

    // ---------- CopyIn ----------
    __aicore__ inline void CopyInX(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, inputGM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyInR1(int32_t rowIdx)
    {
        r1InLocal_ = r1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r1InLocal_, r1GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r1InQueue_.EnQue(r1InLocal_);
    }

    __aicore__ inline void CopyInR2(int32_t rowIdx)
    {
        r2InLocal_ = r2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(r2InLocal_, r2GM_[static_cast<uint64_t>(rowIdx) * D], static_cast<uint32_t>(D));
        r2InQueue_.EnQue(r2InLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
