    // ---------- Compute: half mode ----------
    // out[:halfD] = x[:halfD] * r1[:halfD] - x[halfD:D] * r2[:halfD]
    // out[halfD:D] = x[halfD:D] * r1[halfD:D] + x[:halfD] * r2[halfD:D]
    __aicore__ inline void ComputeHalf(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &r1Local,
        AscendC::LocalTensor<float> &r2Local,
        AscendC::LocalTensor<float> &outBuf)
    {
        // Compute first half: out[:halfD] = x[:halfD] * r1[:halfD] - x[halfD:] * r2[:halfD]
        AscendC::Mul(outBuf, xLocal, r1Local, halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(outBuf[halfD], xLocal[halfD], r2Local, halfD);
        AscendC::PipeBarrier<PIPE_V>();
