        AscendC::Mul(outBuf[halfD], xLocal[halfD], r1Local[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(r2Local, xLocal, r2Local[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(outBuf[halfD], outBuf[halfD], r2Local, halfD);
