    // Interleave: scattered_write evens[k] → out[2k], odds[k] → out[2k+1]
    __aicore__ inline void InterleaveWrite(
        AscendC::LocalTensor<float> &evens,
        AscendC::LocalTensor<float> &odds,
        AscendC::LocalTensor<float> &out)
    {
        for (int i = 0; i < halfD; ++i) {
            out.SetValue(2 * i, evens.GetValue(i));
            out.SetValue(2 * i + 1, odds.GetValue(i));
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ComputeInterleave(
        AscendC::LocalTensor<float> &xLocal,
