    // ---------- Compute ----------
    __aicore__ inline void Compute()
    {
        AscendC::LocalTensor<float> xLocal = buf0_.Get<float>();
        AscendC::LocalTensor<float> r1Local = buf1_.Get<float>();
        AscendC::LocalTensor<float> r2Local = buf2_.Get<float>();
        AscendC::LocalTensor<float> outBuf = buf3_.Get<float>();

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

