            AscendC::DataCopyParams dcParams;
            dcParams.blockCount = 1;
            dcParams.blockLen = static_cast<uint32_t>(D) * static_cast<uint32_t>(sizeof(float));
            dcParams.srcGap = 0;
            dcParams.dstGap = 0;
