    // ---------- Simplified interleave using element-wise access ----------
    // Formula: for each pair (2k, 2k+1):
    //   out[2k]   = x[2k]*r1[2k] - x[2k+1]*r2[2k]
    //   out[2k+1] = x[2k+1]*r1[2k+1] + x[2k]*r2[2k+1]
    __aicore__ inline void ComputeSimpleInterleave(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &r1Local,
        AscendC::LocalTensor<float> &r2Local,
        AscendC::LocalTensor<float> &outBuf)
    {
        // Use scalar loop for each pair (D <= 128, halfD <= 64, OK for performance)
