            float r2_even = r2Local.GetValue(2 * k);
            float r2_odd = r2Local.GetValue(2 * k + 1);
            outBuf.SetValue(2 * k, x_even * r1_even - x_odd * r2_even);
            outBuf.SetValue(2 * k + 1, x_odd * r1_odd + x_even * r2_odd);
        }
        AscendC::PipeBarrier<PIPE_V>();
