    // ---------- ProcessRow ----------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyInX(rowIdx);
        CopyInR1(rowIdx);
        CopyInR2(rowIdx);
        Compute();
        CopyOutY(rowIdx);
    }

