    // ---------- Compute: half mode (vectorized) ----------
    // out[:halfD]  = x[:halfD] * r1[:halfD] - x[halfD:D] * r2[:halfD]
    // out[halfD:D] = x[halfD:D] * r1[halfD:D] + x[:halfD] * r2[halfD:D]
    __aicore__ inline void ComputeHalf(
        AscendC::LocalTensor<float> &x,
        AscendC::LocalTensor<float> &r1,
        AscendC::LocalTensor<float> &r2,
        AscendC::LocalTensor<float> &out)
    {
        // First half part 1: tmp = x[:halfD] * r1[:halfD] → out[:halfD]
        AscendC::Mul(out, x, r1, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // First half part 2: out[:halfD] -= x[halfD:D] * r2[:halfD]
        // r2[:halfD] * (-1) then mul-add
        AscendC::Muls(r2, r2, -1.0f, halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(r2, r2, x[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(out, out, r2, halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // Second half part 1: tmp = x[halfD:D] * r1[halfD:D] → out[halfD:D]
        AscendC::Mul(out[halfD], x[halfD], r1[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();

        // Second half part 2: tmp2 = x[:halfD] * r2[halfD:D]
        AscendC::Mul(r2[halfD], x, r2[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(out[halfD], out[halfD], r2[halfD], halfD);
        AscendC::PipeBarrier<PIPE_V>();
