        AscendC::LocalTensor<float> xEven = r1;  // reuse r1 buffer for x_evens
        AscendC::LocalTensor<float> xOdd = r2;   // reuse r2 buffer for x_odds
        AscendC::LocalTensor<float> r1Even = buf3_.Get<float>();  // scratch
        AscendC::LocalTensor<float> r1Odd = out;   // reuse output buffer for r1 odds

        // But wait, r1 and r2 are input buffers. Let me use buf3 carefully.
        // Actually, this approach of reusing buffers is getting complicated.
        // Let me just use a simpler direct computation.

        // DIRECT COMPUTATION: use scalar access for each pair
        // Total ops: halfD * 6 scalar loads + halfD * 2 scalar stores = ~512 ops for D=128
        // This is in the Compute() inner loop, on UB only, no GM access → fast

        for (int k = 0; k < halfD; ++k) {
