        // Step 1: DeQue typed inputs
        xInLocal_ = xInQueue_.DeQue<dataType>();
        r1InLocal_ = r1InQueue_.DeQue<dataType>();
        r2InLocal_ = r2InQueue_.DeQue<dataType>();

