        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> yFloat = yOutLocal_.template ReinterpretCast<float>();
            // DataCopy to copy from outFp32(TBuf) to yFloat(TQue output)
            // Use DataCopy with DataCopyParams for UB→UB
            AscendC::DataCopyParams params;
            params.blockCount = 1;
            params.blockLen = static_cast<uint32_t>(D) * static_cast<uint32_t>(sizeof(float));
            params.srcGap = 0;
            params.dstGap = 0;
            AscendC::DataCopy(yFloat, outFp32, params);
        } else {
            AscendC::Cast(yOutLocal_, outFp32, GetOutputCastMode<dataType>(), D);
            AscendC::PipeBarrier<PIPE_V>();
        }

